@Override
public MediaType detect(TikaInputStream tis, Metadata metadata, ParseContext parseContext) throws IOException {
    String type = metadata.get(TikaCoreProperties.CONTENT_TYPE_PARSER_OVERRIDE);
    if (type != null) {
        return MediaType.parse(type);
    }
    type = metadata.get(TikaCoreProperties.CONTENT_TYPE_USER_OVERRIDE);
    if (type != null) {
        return MediaType.parse(type);
    } else {
        return MediaType.OCTET_STREAM;
    }
}
